import math

# Witness should be a tuple of 4 integers: (n, m, a, k)
# representing:
# R = Z/nZ  (n=0 means Z)
# S = Z/mZ  (m=0 means Z)
# f: R -> S given by f(x) = a*x mod m
# I = kR    (ideal generated by k in R)

def conditions(witness):
    try:
        if len(witness) != 4:
            return [False, False, False, False]
            
        n, m, a, k = [int(x) for x in witness]
        
        # H1: R and S are rings
        # Z/nZ and Z/mZ are always rings for any integers n, m
        h1 = True
        
        # H2: f: R -> S is a ring homomorphism
        # f(x) = a*x mod m
        if m == 0:
            well_def_f = (a * n == 0)
            mult_f = (a**2 == a)
        else:
            well_def_f = ((a * n) % m == 0)
            mult_f = ((a**2 - a) % m == 0)
            
        h2 = well_def_f and mult_f
        
        # H3: pi: R -> R/I is the canonical projection homomorphism
        # By construction, I is the ideal generated by k, and pi is the canonical projection
        h3 = True
        
        # Negated Conclusion:
        # The conclusion states there exists a unique ring homomorphism f_bar: R/I -> S 
        # such that f = f_bar o pi.
        # Since pi is surjective, if f_bar exists, it is unique.
        # f_bar exists if and only if I is a subset of ker(f).
        # Since I is generated by k, we need f(k) = 0 in S.
        if m == 0:
            f_bar_exists = (a * k == 0)
        else:
            f_bar_exists = ((a * k) % m == 0)
            
        neg_q = not f_bar_exists
        
        return [h1, h2, h3, neg_q]
    except Exception:
        return [False, False, False, False]

CONDITION_LABELS = [
    "H_1: R and S are rings",
    "H_2: f: R -> S is a ring homomorphism",
    "H_3: pi: R -> R/I is the canonical projection homomorphism",
    "¬Q: There does not exist a unique ring homomorphism f_bar: R/I -> S such that f = f_bar o pi"
]

N_HYP = 3
NEG_Q_INDEX = 3